def max_path_sum(triangle, rows, cols):
    # The triangle is stored in a 2D list where row i has (i+1) elements,
    # but the list is padded with zeros to make it rectangular (rows x cols).
    # We need to find the maximum path sum from top to bottom.

    # Create a DP table
    dp = [[0] * cols for _ in range(rows)]

    # Initialize the top
    dp[0][0] = triangle[0][0]

    # Fill the DP table
    for i in range(1, rows):
        for j in range(i + 1):  # row i has i+1 elements (indices 0 to i)
            if j == 0:
                dp[i][j] = dp[i-1][j] + triangle[i][j]
            elif j == i:
                dp[i][j] = dp[i-1][j-1] + triangle[i][j]
            else:
                dp[i][j] = max(dp[i-1][j-1], dp[i-1][j]) + triangle[i][j]

    # The answer is the maximum value in the last row
    last_row = rows - 1
    max_sum = 0
    for j in range(last_row + 1):
        if dp[last_row][j] > max_sum:
            max_sum = dp[last_row][j]

    return max_sum
