def min_Operations(a, b):
    if a == b:
        return 0
    if a > b:
        a, b = b, a
    # We need to make a equal to b
    # Operations: increment a by 1, or double a
    # We want minimum operations to go from a to b
    # Work backwards from b: if b is even, we could have come from b//2 (by doubling) or b-1 (by incrementing)
    # If b is odd, we must have come from b-1 (by incrementing)
    # Count operations going from b down to a
    ops = 0
    while b > a:
        if b % 2 == 0:
            if b // 2 >= a:
                b = b // 2
            else:
                b = b - 1
        else:
            b = b - 1
        ops += 1
    # Now b <= a, we need to increment b to a
    ops += a - b
    return ops
```

