    if int(math.isqrt(n)) ** 2 == n:
        return 1
    # Check if n can be expressed as sum of two squares
    for i in range(1, int(math.isqrt(n)) + 1):
        if int(math.isqrt(n - i * i)) ** 2 == n - i * i:
            return 2
    # Check if n can be expressed as sum of three squares
    # By Legendre's three-square theorem, n is not of the form 4^a*(8b+7)
