def find_Divisor(start, end):
    from collections import Counter

    # Count occurrences of each divisor for all numbers in [start, end]
    divisor_count = Counter()

    for num in range(start, end + 1):
        # Find all divisors of num
        i = 1
        while i * i <= num:
            if num % i == 0:
                divisor_count[i] += 1
                if i != num // i:
                    divisor_count[num // i] += 1
            i += 1

    # Find the divisor with maximum count
    max_count = max(divisor_count.values())
    # Among divisors with max count, return the largest one
    candidates = [d for d, c in divisor_count.items() if c == max_count]
    return max(candidates)
