def is_subset_sum(arr, n, target):
    # dp[i][s] = True if there is a subset of arr[0..i-1] with sum s
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: sum 0 is always possible with empty subset
    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for s in range(1, target + 1):
            # Don't include arr[i-1]
            dp[i][s] = dp[i - 1][s]
            # Include arr[i-1] if possible
