def get_cells(grid):
    """Get list of (r, c) cells that are '#' in the grid."""
    cells = []
    for r in range(4):
        for c in range(4):
            if grid[r][c] == '#':
                cells.append((r, c))
    return cells

def normalize(cells):
    """Normalize cells so that the top-leftmost cell is at (0,0)."""
    if not cells:
        return []
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    normalized = [(r - min_r, c - min_c) for r, c in cells]
    return sorted(normalized)

def rotate_cells(cells):
    """Rotate cells 90 degrees clockwise. (r, c) -> (c, -r) then normalize."""
    rotated = [(c, -r) for r, c in cells]
    return normalize(rotated)

def get_all_rotations(cells):
    """Get all unique rotations of the polyomino."""
    rotations = set()
    current = normalize(cells)
    for _ in range(4):
        rotations.add(tuple(current))
        current = rotate_cells(current)
