    # dp[i][j][k] = max coins at cell (i,j) with k neutralizations used
    # k can be 0, 1, or 2
    # Initialize with -infinity
    NEG_INF = float('-inf')

    # dp[i][j][k] for i in range(m), j in range(n), k in range(3)
    dp = [[[NEG_INF] * 3 for _ in range(n)] for _ in range(m)]

