        if grid[0][0] < 0:
            # If we use a neutralization at start
            if k >= 1:
                dp[0][0][k] = 0  # neutralized, so no loss
            else:
                dp[0][0][k] = grid[0][0]  # robber steals
        else:
            dp[0][0][k] = grid[0][0]

    # Fill the dp table
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
