                    # Robber cell
                    # Option 1: Don't neutralize, lose abs(grid[i][j])
                    val_no_neutral = best + grid[i][j]
                    # Option 2: Neutralize (if we have neutralizations left)
                    if k > 0:
                        # We used one neutralization at this cell
                        # The previous state had k-1 neutralizations used
                        # But we already took best from prev_k in range(k+1)
                        # We need to be more careful: if we neutralize, we use 1 neutralization
                        # So the previous state must have used k-1 neutralizations
                        # Let's recompute:
