                    compatible[i][j] = True

    # DP over subsets: dp[mask][last] = number of ways to arrange elements in mask ending with 'last'
    # mask is a bitmask of which elements have been used
    # last is the index of the last element

    from functools import lru_cache

    @lru_cache(maxsize=None)
