def punishment_number(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        if not s:
            return target == 0
        if target < 0:
            return False
        # Try all possible partitions
        for i in range(1, len(s) + 1):
            part = int(s[:i])
            if part > target:
                break
            if can_partition(s[i:], target - part):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        sq = i * i
        s = str(sq)
        if can_partition(s, i):
            total += sq
    return total

if __name__ == "__main__":
    import sys
    n = int(sys.stdin.read().strip())
    print(punishment_number(n))
